<header class="portal-shell" data-portal-shell="1"><div class="wrap"><a class="brand" href="<?=$e($c['prefix'].'/')?>" aria-label="Explorando Lugares, <?=$e($t['home'])?>"><img class="brand-logo" src="<?=$e(self::config()['logo'])?>" alt="" width="420" height="420"><span>Explorando <b>Lugares</b></span></a><div class="header-language-bar"><span class="language-switch" aria-label="<?=$e($t['account'])?>"><span class="portal-account-strip portal-account-inline"<?=$c['legacy_admin']?' data-admin-legacy':''?> aria-label="<?=$e($t['account'])?>"><span class="portal-account-strip-inner"><?php if($c['legacy_admin']):?><details class="account-user-menu"><summary class="account-name">Administrador</summary><div class="account-user-menu-panel"><a href="/admin/index.php">Administración</a><form method="post" action="/admin/index.php"><input type="hidden" name="csrf" value="<?=$e($c['csrf'])?>"><input type="hidden" name="action" value="logout"><button type="submit">Cerrar sesión</button></form></div></details><?php else:?><a href="/negocios/acceso/<?=$c['locale']==='es'?'':'?lang='.$e(strtolower($c['locale']))?>"><?=$e($t['login'])?></a><a class="header-register" href="/negocios/registro/<?=$c['locale']==='es'?'':'?lang='.$e(strtolower($c['locale']))?>"><?=$e($t['register'])?></a><?php endif;?></span></span></span><nav class="header-language-options" aria-label="Idioma / Language"><?php foreach(['es'=>['🇨🇴','ES','Español'],'en'=>['🇬🇧','EN','English'],'pt-BR'=>['🇧🇷','PT-BR','Português']] as $language=>$label):$option=$c['language_navigation'][$language];?><a href="<?=$e($option['href'])?>" lang="<?=$e($language)?>"<?=$option['equivalent']?' hreflang="'.$e($language).'"':''?> aria-label="<?=$e($option['description']??$label[2])?>"<?=$option['description']?' title="'.$e($option['description']).'"':''?><?=$c['locale']===$language&&$option['equivalent']?' aria-current="page"':''?> data-language-target="<?=$option['equivalent']?'equivalent-page':'portal-home'?>"><span class="header-language-flag" aria-hidden="true"><?=$label[0]?></span><span><?=$e($option['label']??$label[1])?></span></a><?php endforeach;?></nav></div><button type="button" class="menu-toggle" aria-controls="menu-principal" aria-expanded="false" aria-label="<?=$e($t['menu'])?>"><span></span><span></span><span></span></button><nav id="menu-principal" aria-label="Principal"><?php foreach(self::config()['navigation'] as [$key,$path,$localized]):$url=($localized?$c['prefix']:'').$path;$active=$path==='/'?$c['path']==='/':str_starts_with($c['path'],$path);?><a href="<?=$e($url)?>"<?=$active?' aria-current="page"':''?>><?=$e($t[$key])?></a><?php endforeach;?></nav></div><div class="header-note wrap"><span><?=$e($t['intro'])?></span><span><?=$e($t['tag'])?></span></div></header>
